const { bundleJs, bundleCss, inlinedExternals } = await bundleToIife({
  entry: bundleEntry,
  globalName: GLOBAL,
  nodePaths: NODE_MODULES,
  out: OUT,
  tsconfig: TSCONFIG_PATH,
});
